import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

def find_sheet(names, target):
    for name in names:
        if str(name).strip().upper() == target:
            return name
    return target

whp_name = find_sheet(vals.sheetnames, "WHP")
data_name = find_sheet(vals.sheetnames, "WHP DATA")

whp_vals = vals[whp_name]
data_vals = vals[data_name]

def is_num(v):
    if isinstance(v, bool):
        return False
    if isinstance(v, (int, float)):
        return True
    if isinstance(v, str):
        try:
            float(v.strip())
            return True
        except Exception:
            return False
    return False

def to_num(v):
    if v is None:
        return 0
    if isinstance(v, bool):
        return int(v)
    if isinstance(v, (int, float)):
        return v
    if isinstance(v, str):
        s = v.strip()
        if not s:
            return 0
        try:
            return float(s)
        except Exception:
            return 0
    return 0

exclude = {
    "total",
    "referral type",
    "go live 1/3/18",
    "local london partnership",
    "central london forward",
    "eeg",
    "dis",
    "ltu",
    "ytd",
}

mapping = {}

for row in data_vals.iter_rows(min_row=1, max_row=data_vals.max_row, min_col=1, max_col=5):
    b = row[1].value if len(row) > 1 else None
    if b is None:
        continue

    site = str(b).strip()
    if not site or site.lower() in exclude:
        continue

    c = row[2].value if len(row) > 2 else None
    d = row[3].value if len(row) > 3 else None
    e = row[4].value if len(row) > 4 else None

    if any(v is not None and not is_num(v) for v in (c, d, e)):
        continue

    key = site.lower()
    prev = mapping.get(key, (0, 0, 0))
    mapping[key] = (
        prev[0] + to_num(c),
        prev[1] + to_num(d),
        prev[2] + to_num(e),
    )

def clean_number(x):
    if isinstance(x, float) and x.is_integer():
        return int(x)
    return x

whp = wb[whp_name]

for r in range(7, 9):
    site = None
    for col in range(1, 5):
        v = whp_vals.cell(row=r, column=col).value
        if v is None:
            continue
        s = str(v).strip()
        if s.lower() == "referrals":
            continue
        site = s
        break

    if site is None:
        continue

    key = site.lower()
    eeg, dis, ltu = mapping.get(key, (0, 0, 0))

    whp.cell(row=r, column=5).value = clean_number(eeg)
    whp.cell(row=r, column=6).value = clean_number(dis)
    whp.cell(row=r, column=7).value = clean_number(ltu)

    print(f"Wrote row {r}: {site} -> EEG={eeg}, Dis={dis}, LTU={ltu}")

print("Mapping:", mapping)
wb.save(OUT)
